\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Venue Color Theme ──
\definecolor{primary}{HTML}{0B101E}       % Deep navy background
\definecolor{secondary}{HTML}{034EA2}     % Samsung blue
\definecolor{accent}{HTML}{D4AF37}        % Gold/Copper

\definecolor{bgposter}{HTML}{0B101E}      % Poster background

% Card background colors (tinted dark colors)
\definecolor{cardbg}{HTML}{131A2A}        % standard card
\definecolor{bluebg}{HTML}{0F1E3A}        % blue tinted card
\definecolor{goldbg}{HTML}{1F1C12}        % gold tinted card

\definecolor{cardtitlebg}{HTML}{182236}   % title bar on cards
\definecolor{bluetitlebg}{HTML}{142A51}   % title bar on blue cards
\definecolor{goldtitlebg}{HTML}{2B2618}   % title bar on gold cards

\definecolor{textmain}{HTML}{FFFFFF}      % white text
\definecolor{textgray}{HTML}{94A3B8}      % cool silver

\definecolor{stathighlight}{HTML}{1A2B4C}

\pagecolor{bgposter}
\color{textmain}

% ── List styling ──
\setlist[itemize]{leftmargin=30pt, itemsep=10pt, parsep=4pt, topsep=4pt,
  label={\color{secondary}\Large$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=30pt, itemsep=10pt, parsep=4pt, topsep=4pt,
  label={\color{accent}\bfseries\Large\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={8pt}{0pt}{secondary},
    left=20pt, right=20pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{44}{54}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=3pt, titlerule style={secondary!60!black},
    valign=top, drop shadow={opacity=0.3, shadow xshift=4pt, shadow yshift=-4pt},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={8pt}{0pt}{secondary!70!white},
    left=20pt, right=20pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{44}{54}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=bluetitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=3pt, titlerule style={secondary!80!white},
    valign=top, drop shadow={opacity=0.3, shadow xshift=4pt, shadow yshift=-4pt},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={8pt}{0pt}{accent},
    left=20pt, right=20pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{44}{54}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=goldtitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=3pt, titlerule style={accent!60!black},
    valign=top, drop shadow={opacity=0.3, shadow xshift=4pt, shadow yshift=-4pt},
