\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=6mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textmain,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=12pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.5, shadow xshift=0pt, shadow yshift=-6pt}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{100}{120}\selectfont\bfseries SAMSUNG GALAXY ECOSYSTEM 2025}\\[24pt]
  {\fontsize{48}{58}\selectfont\color{textgray} Innovation Across Every Category}\\[12pt]
  {\fontsize{34}{44}\selectfont\color{secondary} \textbf{SAMSUNG} | \textbf{Galaxy}}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!95!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=10pt, bottom=10pt,
  valign=center, borderline south={4pt}{0pt}{secondary!60},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{76}{92}\selectfont\bfseries\color{white} 7+}\\[12pt]
      {\fontsize{32}{38}\selectfont\color{textgray} Product Categories}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{76}{92}\selectfont\bfseries\color{accent} 2}\\[12pt]
      {\fontsize{32}{38}\selectfont\color{textgray} Flagship Launches}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{76}{92}\selectfont\bfseries\color{white} 14}\\[12pt]
      {\fontsize{32}{38}\selectfont\color{textgray} Featured Products}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{76}{92}\selectfont\bfseries\color{white} 4+}\\[12pt]
      {\fontsize{32}{38}\selectfont\color{textgray} AI-Branded Products}\vspace{12pt}%
    }}
  \end{minipage}
}

% ══ NEW LAUNCH 1: GALAXY S26 ULTRA ══
\posterbox[goldcard, title={NEW FLAGSHIP: GALAXY S26 ULTRA}
]{name=hero1, column=1, between=row5 and row10}{
  \fontsize{38}{50}\selectfont\color{textmain}
  \vspace{8pt}
  \colorbox{accent!30}{\parbox{0.94\linewidth}{%
    \centering \textbf{SAMSUNG'S MOST ADVANCED SMARTPHONE}
  }}\vspace{20pt}

  \begin{itemize}[itemsep=16pt]
    \item \textbf{Premium Materials}: Built for ultimate durability and feel.
    \item \textbf{Pro-Grade Cameras}: Next-generation optical excellence.
    \item \textbf{Integrated S Pen}: Enhanced precision and latency.
    \item \textbf{Galaxy AI}: Real-time translation, productivity and photography.
  \end{itemize}
  \vspace{24pt}
  \centering
  \colorbox{accent!20}{\parbox{0.8\linewidth}{%
    \centering \fontsize{34}{44}\selectfont \textit{The ultra experience redefined.}
  }}
}

% ══ NEW LAUNCH 2: GALAXY BUDS4 PRO ══
\posterbox[goldcard, title={NEW FLAGSHIP: GALAXY BUDS4 PRO}
]{name=hero2, column=2, between=row5 and row10}{
