  \vspace{8pt}
  \colorbox{accent!30}{\parbox{0.94\linewidth}{%
    \centering \textbf{NEXT-GENERATION AUDIO}
  }}\vspace{20pt}

  \begin{itemize}[itemsep=16pt]
    \item \textbf{High-Fidelity Sound}: Uncompromising studio-quality audio.
    \item \textbf{Advanced ANC}: Intelligent active noise cancellation.
    \item \textbf{Seamless Pairing}: Instant connection across Galaxy devices.
    \item \textbf{Comfort Fit}: Redesigned for all-day wearability.
  \end{itemize}
  \vspace{24pt}
  \centering
  \colorbox{accent!20}{\parbox{0.8\linewidth}{%
    \centering \fontsize{34}{44}\selectfont \textit{Immersive sound, perfectly connected.}
  }}
