    $\blacktriangleright$ \textbf{Smartphones}: S26 Ultra\\
    $\blacktriangleright$ \textbf{Foldables}: Z Fold7, Z Flip7\\
    $\blacktriangleright$ \textbf{Tablets}: Tab S11 Series\\
    $\blacktriangleright$ \textbf{Wearables}: Watch Ultra, Buds4 Pro
  \end{minipage}\hfill
  \begin{minipage}{0.31\linewidth}
    \colorbox{cardtitlebg}{\parbox{\linewidth}{%
      \vspace{8pt}\centering \textbf{HOME ENTERTAINMENT}\vspace{8pt}%
    }}\vspace{12pt}\\
    \fontsize{34}{44}\selectfont
    $\blacktriangleright$ \textbf{TVs}: Neo QLED 8K, The Frame Pro\\
    $\blacktriangleright$ \textbf{Audio}: Q-series Soundbar\\
    $\blacktriangleright$ \textbf{Monitors}: Odyssey OLED G9
  \end{minipage}\hfill
  \begin{minipage}{0.31\linewidth}
    \colorbox{cardtitlebg}{\parbox{\linewidth}{%
