    \hline
    \rowcolor{cardtitlebg}
    Smartphones & Galaxy S26 Ultra & \textbf{\color{accent}NEW} \\
    \hline
    \rowcolor{primary!50}
    Audio & Galaxy Buds4 Pro & \textbf{\color{accent}NEW} \\
    \hline
    \rowcolor{cardtitlebg}
    Foldables & Galaxy Z Fold7 / Z Flip7 & Current \\
    \hline
    \rowcolor{primary!50}
    Tablets & Galaxy Tab S11 Series & Current \\
    \hline
    \rowcolor{cardtitlebg}
    Wearables & Galaxy Watch Ultra & Current \\
    \hline
    \rowcolor{primary!50}
    Television & Neo QLED 8K TV / The Frame Pro & Current \\
    \hline
    \rowcolor{cardtitlebg}
    Kitchen & Bespoke AI Refrigerator & Current \\
    \hline
    \rowcolor{primary!50}
    Laundry & Bespoke AI Laundry & Current \\
    \hline
  \end{tabular}
}

% ══ FOOTER ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textgray,
  arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=8pt, bottom=8pt,
  halign=center, valign=center
